// Execute modern virtio-MMIO requests on QEMU's AArch64 virt machine.
// Input is generated by indirect_oracle.py; only semihosting exit is used.
.section .text
.global _start
_start:
    msr daifset, #15
    ldr x0, =0x40200000
    mov sp, x0
    ldr x21, =0x40100000
    mov x0, x21
    ldr x1, =0x20000
1:  str xzr, [x0], #8
    subs x1, x1, #8
    b.ne 1b
    ldr x24, =0x09000000
    ldr x20, =input
    ldr w26, [x20, #8]
    ldr w22, [x20, #12]
    add x20, x20, #16
    ldr x19, =0x0a000000
    mov w1, #32
2:  ldr w0, [x19, #8]
    cmp w0, #2
    b.eq 3f
    add x19, x19, #0x200
    subs w1, w1, #1
    b.ne 2b
    b failure
3:  ldr w0, [x19, #4]
    cmp w0, #2
    b.ne failure
    str wzr, [x19, #0x70]
    mov w0, #3
    str w0, [x19, #0x70]
    str wzr, [x19, #0x24]
    str w26, [x19, #0x20]
    mov w0, #1
    str w0, [x19, #0x24]
    str w0, [x19, #0x20]
    mov w0, #11
    str w0, [x19, #0x70]
    ldr w0, [x19, #0x70]
    tst w0, #8
    b.eq failure
    str wzr, [x19, #0x30]
    mov w0, #16
    str w0, [x19, #0x38]
    str w21, [x19, #0x80]
    str wzr, [x19, #0x84]
    add x0, x21, #0x1000
    str w0, [x19, #0x90]
    str wzr, [x19, #0x94]
    add x0, x21, #0x2000
    str w0, [x19, #0xa0]
    str wzr, [x19, #0xa4]
    mov w0, #1
    str w0, [x19, #0x44]
    mov w0, #15
    str w0, [x19, #0x70]
    ldr x0, =magic
    mov w1, #8
    bl emit_bytes
    mov w0, w22
    bl emit_word
    str wzr, [x19, #0x14]
    ldr w0, [x19, #0x10]
    bl emit_word
    mov w0, #1
    str w0, [x19, #0x14]
    ldr w0, [x19, #0x10]
    bl emit_word
    ldr w0, [x19, #0x34]
    bl emit_word
    mov w23, #0
command:
    cmp w23, w22
    b.eq success
    ldr w27, [x20], #4
writes:
    cbz w27, submitted
    ldp w0, w1, [x20], #8
    add x2, x21, w0, uxtw
    add x3, x20, w1, uxtw
    add x3, x3, #3
    and x3, x3, #-4
4:  cbz w1, 5f
    ldrb w0, [x20], #1
    strb w0, [x2], #1
    sub w1, w1, #1
    b 4b
5:  mov x20, x3
    sub w27, w27, #1
    b writes
submitted:
    ldp w28, w29, [x20], #8
    and w0, w23, #15
    add x1, x21, #0x1000
    add x2, x1, #4
    strh w28, [x2, w0, uxtw #1]
    add w0, w23, #1
    strh w0, [x1, #2]
    dsb sy
    str wzr, [x19, #0x50]
    add x25, x21, #0x2000
    mov w2, #0x4000000
6:  ldrh w1, [x25, #2]
    cmp w1, w0
    b.eq completed
    subs w2, w2, #1
    b.ne 6b
    b failure
completed:
    dsb sy
    and w0, w23, #15
    add x0, x25, w0, uxtw #3
    add x0, x0, #4
    mov w1, #8
    bl emit_bytes
    ldrh w0, [x25, #2]
    bl emit_word
    ldr w0, [x19, #0x60]
    bl emit_word
    ldr w0, [x19, #0x70]
    bl emit_word
outputs:
    cbz w29, next_command
    ldp w0, w1, [x20], #8
    add x0, x21, w0, uxtw
    bl emit_bytes
    sub w29, w29, #1
    b outputs
next_command:
    mov w0, #3
    str w0, [x19, #0x64]
    add w23, w23, #1
    b command
success:
    mov w2, #0
    b exit
failure:
    ldr x0, =failure_magic
    mov w1, #8
    bl emit_bytes
    mov w2, #1
exit:
    mov x0, #0x26
    movk x0, #2, lsl #16
    stp x0, x2, [sp, #-16]!
    mov x1, sp
    mov x0, #0x20
    hlt #0xf000
7:  wfe
    b 7b
emit_word:
    str w0, [sp, #-16]!
    str x30, [sp, #8]
    mov x0, sp
    mov w1, #4
    bl emit_bytes
    ldr x30, [sp, #8]
    add sp, sp, #16
    ret
emit_bytes:
    cbz w1, 9f
8:  ldr w2, [x24, #0x18]
    tbnz w2, #5, 8b
    ldrb w3, [x0], #1
    strb w3, [x24]
    subs w1, w1, #1
    b.ne 8b
9:  ret
.balign 8
magic: .ascii "RAXVIOI1"
failure_magic: .ascii "VIOFAIL!"
.balign 8
input: .incbin "input.bin"
